import asyncio

async def slow_service():
    await asyncio.sleep(0.2)
    return 'Fresh DB Response'

async def safe_call():
    try:
        return await asyncio.wait_for(slow_service(), timeout=0.05)
    except asyncio.TimeoutError:
        return '⚡ Fallback to Redis Cache (Timed Out)'

print(asyncio.run(safe_call()))

